726:     let x = (local_timestamps[i] - reference).to_double()
727:     let y = (reference_timestamps[i] - local_timestamps[i]).to_double()
728:     sx = sx + x
729:     sy = sy + y
730:     sxx = sxx + x * x
731:     sxy = sxy + x * y
732:   }
